def sum_to(n):
    total = 0
    for i in range(1, n + 1):
        total = total + i
    return total

def count_down(n):
    result = []
    for i in range(n, 0, -1):
        result.append(i)
    return result

def stairs(n):
    rows = []
    for i in range(1, n + 1):
        rows.append("#" * i)
    return "\n".join(rows)
